import {STORAGE_KEY,freshProgress,shuffle,grade,scheduleCard,recordAnswer,metrics,validateProgress} from './study-engine.mjs';
import {neuronSvg,cordSvg,neuronParts,phases,potentialSvg,reflexSteps} from './anatomy.mjs';

const main = document.querySelector('#main');
const escapeHtml = value => String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const typeNames = {single:'Multiple choice',multiple:'Select all that apply',sequence:'Put in order',recall:'Written recall',label:'Identify a structure'};
let course,questions,cards,state,session,clockInterval,animationInterval,audioUrl,toastTimeout,flashQueue=[],flashPosition=0,flashRevealed=false;
let labMode='neuron',labActive=0,labIdentify=false,labAnswerShown=false;
let storageAvailable=true;

function save() {
  state.session=session&&!session.finished?session:null;
  try {localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
  catch {storageAvailable=false;document.querySelector('.local-tag').textContent='Storage unavailable — export progress';toast('Progress is in memory only. Use Settings → Export to keep it.');}
  document.querySelector('#due-badge').textContent=cards.filter(card=>!state.cards[card.id]||state.cards[card.id].due<=Date.now()).length;
}
function toast(message) {const target=document.querySelector('#toast');target.textContent=message;target.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>target.classList.remove('visible'),4500);}
function confirmAction(message) {
  return new Promise(resolve=>{
    const dialog=document.createElement('dialog');
    dialog.className='confirm-dialog';dialog.setAttribute('aria-labelledby','confirm-title');
    dialog.innerHTML=`<form method="dialog"><h2 id="confirm-title">Confirm your choice</h2><p>${escapeHtml(message)}</p><div class="row"><button value="cancel" autofocus>Cancel</button><button class="primary" value="confirm">Confirm</button></div></form>`;
    dialog.addEventListener('close',()=>{const accepted=dialog.returnValue==='confirm';dialog.remove();resolve(accepted);},{once:true});
    document.body.append(dialog);dialog.showModal();
  });
}
function applySettings() {document.documentElement.dataset.theme=state.settings.theme;document.documentElement.classList.toggle('custom-cursor',state.settings.cursor);document.documentElement.classList.toggle('reduce-motion',!state.settings.motion);document.querySelector('#theme-toggle').setAttribute('aria-label',`Switch to ${state.settings.theme==='dark'?'light':'dark'} theme`);}
function intro(title,subtitle,extra='') {return `<div class="page-intro"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
function empty(title,message,link='#practice',label='Choose a practice set') {return `<div class="panel empty"><div class="mode-icon">✳</div><h2>${title}</h2><p class="muted">${message}</p><a class="button" href="${link}">${label}</a></div>`;}
function refs(sources) {return `<div class="source-ref">Source${sources.length===1?'':'s'}: ${sources.map(source=>{const item=course.sources.find(entry=>entry.id===source.id);return `${escapeHtml(item?.title||source.id)} · ${source.pages?.length?'PDF p. '+escapeHtml(source.pages.join(', ')):escapeHtml(source.location||'Lecture transcript')}`;}).join('<br>')}<br>Original study summary / question, not an instructor quotation.</div>`;}
function topicQuestions(topic) {return questions.filter(question=>question.topicId===topic.id);}
function stat(symbol,value,label) {return `<div class="stat"><div class="stat-symbol">${symbol}</div><div><strong>${value}</strong><small>${label}</small></div></div>`;}
function chapterOptions() {return '<option value="all">Both chapters</option><option value="12">Chapter 12</option><option value="13">Chapter 13</option>';}
function topicOptions() {return '<option value="all">All topics</option>'+course.topics.map(topic=>`<option value="${topic.id}">Ch. ${topic.chapter} · ${escapeHtml(topic.title)}</option>`).join('');}
function home() {
  const totals=metrics(questions,state);
  const last=course.topics.find(topic=>topic.id===state.lastTopic)||course.topics[0];
  main.innerHTML=intro('Your next connection starts here.','A little curiosity. A little practice. A lot of progress.','<span class="pill">● &nbsp; EXAM 3 WORKSPACE</span>')+
  `<section class="hero reveal"><div><div class="eyebrow">CHAPTERS 12 & 13 · THE NERVOUS SYSTEM</div><h1>Small signals.<br><em>Big understanding.</em></h1><p>Explore the nervous system, connect structure to function, and turn “I recognize this” into “I know this.”</p><div class="row"><a class="button" href="${session?'#quiz':'#topic/'+last.id}">${session?'Resume practice':'Continue learning'} <span>→</span></a><a class="text-link" href="#practice">Test yourself ↗</a></div></div><div class="hero-art">${neuronSvg(true)}<span class="hero-note">One connection at a time.</span></div></section>`+
  `<div class="stats">${stat('▤',course.topics.length,'Topics to explore')}${stat('◎',totals.accuracy===null?'—':totals.accuracy+'%','Practice accuracy')}${stat('▱',cards.filter(card=>!state.cards[card.id]||state.cards[card.id].due<=Date.now()).length,'Cards ready for review')}${stat('✓',state.completed.length+'/'+course.topics.length,'Lessons marked complete')}</div>`+
  `<div class="section-heading"><h2>Your learning path</h2><a class="text-link" href="#learn">Explore all topics →</a></div><div class="chapter-grid">`+
  [12,13].map(chapter=>{const topics=course.topics.filter(topic=>topic.chapter===chapter);const counts=metrics(questions.filter(question=>question.chapter===chapter),state);return `<a class="chapter-card reveal" href="#learn/${chapter}"><div class="chapter-illustration"><span class="chapter-number">CHAPTER ${chapter}</span>${chapter===12?neuronSvg(true):cordSvg()}</div><div class="chapter-body"><h3>${chapter===12?'Nervous tissue & signaling':'Spinal cord, nerves & reflexes'}</h3><p>${chapter===12?'Meet the cells. Follow the signal. Understand how neurons communicate.':'Trace the pathways that connect your body and coordinate a response.'}</p><div class="chapter-meta"><span>▤ ${topics.length} topics</span><span>◎ ${questions.filter(question=>question.chapter===chapter).length} questions</span></div><div class="meter"><span style="width:${counts.mastery}%"></span></div><div class="chapter-bottom"><span>${counts.mastery}% demonstrated mastery</span><span class="text-link">Start exploring →</span></div></div></a>`;}).join('')+'</div>'+
  `<div class="section-heading"><h2>A different way to make it stick</h2><span class="muted small">ACTIVE RECALL, YOUR WAY</span></div><div class="mode-grid"><a class="mode-card" href="#cards"><div class="mode-icon">▱</div><h3>Flip. Recall. Repeat.</h3><p>Give your memory a workout with spaced flashcard review.</p><span>Open flashcards →</span></a><a class="mode-card" href="#lab"><div class="mode-icon">⌁</div><h3>See the signal.</h3><p>Explore a neuron, an action potential, and a reflex arc.</p><span>Enter the visual lab →</span></a><a class="mode-card" href="#practice/exam"><div class="mode-icon">◷</div><h3>Find your exam rhythm.</h3><p>A timed practice session. Explanations after you submit.</p><span>Build a practice exam →</span></a></div>`+
  `<div class="section-heading"><h2>Your complete study hub</h2></div><div class="row"><a class="button secondary" href="exam1.html">Exam 1 · Chapters 1–4 ↗</a><a class="button secondary" href="lab.html">Exam 2 · Chapters 5–10 ↗</a><a class="button secondary" href="exam2-lab.html">Muscle lab ↗</a><a class="button secondary" href="modern.html">Exam 2 visual guide ↗</a></div><p class="muted small">Existing exams retain their original question banks and saved missed-question lists.</p>`;
}

function learn(chapter='all') {
  main.innerHTML=intro('Follow your curiosity.','Read the idea, explore it, then retrieve it from memory.')+`<div class="row" style="margin-bottom:20px"><a class="button ${chapter==='all'?'':'secondary'}" href="#learn">All topics</a><a class="button ${chapter==='12'?'':'secondary'}" href="#learn/12">Chapter 12</a><a class="button ${chapter==='13'?'':'secondary'}" href="#learn/13">Chapter 13</a></div><div class="search-wrap"><label for="topic-search">Search lessons and lecture summaries</label><input id="topic-search" type="search" placeholder="Try myelin, synapse, dorsal root…"></div><div id="topic-results" class="topic-grid"></div>`;
  function showTopics() {
    const term=document.querySelector('#topic-search').value.toLowerCase();
    const filtered=course.topics.filter(topic=>(chapter==='all'||String(topic.chapter)===chapter)&&[topic.title,topic.summary,...topic.details].join(' ').toLowerCase().includes(term));
    document.querySelector('#topic-results').innerHTML=filtered.map(topic=>{const progress=metrics(topicQuestions(topic),state);return `<a class="topic-tile" href="#topic/${topic.id}"><span class="eyebrow">CHAPTER ${topic.chapter}</span><h3>${escapeHtml(topic.title)}</h3><p>${escapeHtml(topic.summary)}</p><div class="row spread"><span>${topic.questions.length} questions · ${topic.cards.length} cards</span><span>${state.completed.includes(topic.id)?'✓ Read':progress.seen?'In progress':'Start →'}</span></div></a>`;}).join('')||'<p class="muted">No matching topics. Try another term.</p>';
  }
  showTopics();document.querySelector('#topic-search').addEventListener('input',showTopics);
}

function lesson(id) {
  const topic=course.topics.find(item=>item.id===id);
  if(!topic){main.innerHTML=empty('Topic not found','Choose a topic from the learning path.','#learn','Browse topics');return;}
  state.lastTopic=id;save();
  main.innerHTML=`<a class="text-link" href="#learn/${topic.chapter}">← Chapter ${topic.chapter}</a>`+intro(escapeHtml(topic.title),'Understand → Explore → Recall → Apply → Review')+`<div class="lesson-layout"><article class="panel prose"><span class="eyebrow">CHAPTER ${topic.chapter} · ORIGINAL STUDY SUMMARY</span><p>${escapeHtml(topic.summary)}</p>${topic.emphasis?`<div class="emphasis"><b>Emphasis in supplied lecture notes</b><br>${escapeHtml(topic.emphasis)}</div>`:''}<h2>Build the idea</h2><ul>${topic.details.map(detail=>`<li>${escapeHtml(detail)}</li>`).join('')}</ul><details><summary>Check your understanding</summary><p>Close the notes. Explain this topic aloud, then answer: ${escapeHtml(topic.cards[0]?.front||topic.title)}</p><p>Check the details you missed before practicing.</p></details>${refs(topic.sources)}<div class="row" style="margin-top:24px"><button id="complete-lesson" class="secondary">${state.completed.includes(id)?'✓ Marked complete':'Mark lesson complete'}</button><a class="button" href="#practice/topic/${id}">Practice this topic →</a></div><p class="muted small">Marking a lesson complete records reading, not mastery.</p></article><aside class="panel"><h3>Make it stick</h3><a href="#cards/${id}">▱ Review these flashcards →</a><a href="#lab">⌁ Explore the visual lab →</a><a href="#practice/topic/${id}">◎ Answer ${topic.questions.length} questions →</a><a href="#sources">♫ Pair with your recording →</a><hr style="border:0;border-top:1px solid var(--line)"><h3>In this chapter</h3>${course.topics.filter(item=>item.chapter===topic.chapter).map(item=>`<a href="#topic/${item.id}" ${item.id===id?'aria-current="page"':''}>${escapeHtml(item.title)}</a>`).join('')}</aside></div>`;
  document.querySelector('#complete-lesson').onclick=()=>{state.completed=state.completed.includes(id)?state.completed.filter(item=>item!==id):[...state.completed,id];save();lesson(id);};
}

function practiceSetup(parts=[]) {
  const timed=parts[0]==='exam';const topicId=parts[0]==='topic'?parts[1]:'all';const review=['missed','bookmarks','low','lecture-20261110'].includes(parts[0])?parts[0]:'all';
  main.innerHTML=intro(timed?'Make practice feel like exam day.':'Retrieval is where it sticks.',timed?'Choose the scope and time. Answers stay hidden until submission.':'Short sessions. Useful feedback. A clear next step.')+`<form id="practice-form" class="panel"><h2>Build your session</h2><div class="filters"><div><label for="practice-chapter">Chapter</label><select id="practice-chapter">${chapterOptions()}</select></div><div><label for="practice-topic">Topic</label><select id="practice-topic">${topicOptions()}</select></div><div><label for="practice-type">Question type</label><select id="practice-type"><option value="all">All eligible types</option>${Object.entries(typeNames).filter(([key])=>!timed||key!=='recall').map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div><div><label for="practice-review">Review focus</label><select id="practice-review"><option value="all">All questions</option><option value="missed">Last answered incorrectly</option><option value="low">Low confidence</option><option value="bookmarks">Bookmarked</option><option value="lecture-20261110">November 10 lecture — new questions</option></select></div><div><label for="practice-count">Questions (up to available)</label><input id="practice-count" type="number" min="1" max="200" value="${timed?25:10}" required></div><div><label for="practice-minutes">Time limit</label><select id="practice-minutes"><option value="0">Untimed practice</option><option value="5">5 minutes</option><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="60">60 minutes</option></select></div></div><p class="muted" id="available-count"></p><div class="row"><button class="primary" type="submit">Start session →</button>${session?'<a class="button secondary" href="#quiz">Resume saved session</a>':''}<a class="text-link" href="${timed?'#practice':'#practice/exam'}">${timed?'Switch to practice':'Set up a timed exam'} →</a></div><div class="notice">Timed exams exclude written self-assessment. Quiz accuracy, flashcard ratings, and reading completion are tracked separately. Hint use is available in practice only.</div></form>`;
  const topicSelect=document.querySelector('#practice-topic');topicSelect.value=topicId||'all';document.querySelector('#practice-review').value=review;if(timed)document.querySelector('#practice-minutes').value='30';
  function eligible() {
    const chapter=document.querySelector('#practice-chapter').value;const topic=topicSelect.value;const type=document.querySelector('#practice-type').value;const focus=document.querySelector('#practice-review').value;const isTimed=Number(document.querySelector('#practice-minutes').value)>0;
    return questions.filter(question=>(chapter==='all'||String(question.chapter)===chapter)&&(topic==='all'||question.topicId===topic)&&(type==='all'||question.type===type)&&(!isTimed||question.type!=='recall')&&(focus==='all'||focus==='lecture-20261110'&&question.id.startsWith('lecture-20261110-')||focus==='bookmarks'&&state.bookmarks.includes(question.id)||focus==='missed'&&state.answers[question.id]?.lastCorrect===false||focus==='low'&&state.answers[question.id]?.confidence==='low'));
  }
  const update=()=>{document.querySelector('#available-count').textContent=`${eligible().length} questions match your selection.`;};update();document.querySelector('#practice-form').addEventListener('change',update);
  document.querySelector('#practice-form').onsubmit=async event=>{event.preventDefault();const pool=eligible();if(!pool.length){toast('No questions match. Try another filter or practice a topic first.');return;}if(session&&!await confirmAction('Replace the saved session? Answers already checked in practice remain in your progress.'))return;const minutes=Number(document.querySelector('#practice-minutes').value);const count=Math.max(1,Math.min(200,Number(document.querySelector('#practice-count').value)||10));session={ids:shuffle(pool).slice(0,count).map(question=>question.id),pos:0,timed:minutes>0,deadline:minutes?Date.now()+minutes*60000:null,responses:{},orders:{},checked:[],finished:false};save();location.hash='#quiz';};
}

function responseFor(question) {
  if(!session.responses[question.id])session.responses[question.id]={selected:question.type==='sequence'?shuffle(question.options.map((_,index)=>index)):[],text:'',confidence:'medium',self:null};
  if(!session.orders[question.id]&&question.options)session.orders[question.id]=shuffle(question.options.map((_,index)=>index));
  return session.responses[question.id];
}
function answerText(question) {return question.type==='recall'?question.model:question.answer.map(index=>question.options[index]).join(question.type==='sequence'?' → ':'; ');}
function feedback(question,response) {
  const correct=question.type==='recall'?response.self:grade(question,response.selected);
  return `<div class="feedback ${correct?'':'wrong'}" role="status"><h3>${question.type==='recall'?'Your self-assessment':correct?'You made the connection.':'A useful gap to close.'}</h3><p><strong>${question.type==='recall'?'Model answer':'Correct answer'}:</strong> ${escapeHtml(answerText(question))}</p>${question.explanations?.length?`<ul>${question.explanations.map((explanation,index)=>`<li>${question.type==='single'||question.type==='multiple'?`<strong>${escapeHtml(question.options[index])}:</strong> `:''}${escapeHtml(explanation)}</li>`).join('')}</ul>`:''}${refs(question.sources)}</div>`;
}
function quiz() {
  clearInterval(clockInterval);
  if(!session){main.innerHTML=empty('Ready when you are.','Choose a chapter, topic, or review focus to start.');return;}
  if(session.timed&&Date.now()>=session.deadline){finishQuiz(true);return;}
  const question=questions.find(item=>item.id===session.ids[session.pos]);const response=responseFor(question);const checked=session.checked.includes(question.id);
  main.innerHTML=`<div class="question-shell">${intro(session.timed?'Practice exam':'Connect it. Recall it.',`Question ${session.pos+1} of ${session.ids.length}`,session.timed?'<span class="timer" id="timer" aria-label="Time remaining"></span>':'')}<div class="meter"><span style="width:${session.pos/session.ids.length*100}%"></span></div><article class="panel"><div class="row spread"><span class="eyebrow">CHAPTER ${question.chapter} · ${typeNames[question.type]}</span><button id="bookmark-question" aria-pressed="${state.bookmarks.includes(question.id)}">${state.bookmarks.includes(question.id)?'★ Saved':'☆ Save'}</button></div><h2 class="question-heading">${escapeHtml(question.prompt)}</h2>${question.type==='label'?`<div class="diagram">${neuronSvg(false,question.part)}</div>`:''}<div id="answer-area"></div><div id="hint-area"></div><div id="feedback-area"></div><div class="question-tools row spread"><div class="confidence">How sure are you? ${['low','medium','high'].map(value=>`<label><input type="radio" name="confidence" value="${value}" ${response.confidence===value?'checked':''} ${checked?'disabled':''}>${value}</label>`).join('')}</div>${!session.timed&&!checked?'<button id="hint-button">Give me a hint</button>':''}</div><div class="row spread"><div class="row">${session.timed&&session.pos>0?'<button id="previous-question">← Previous</button>':''}<button id="leave-quiz">Save & exit</button></div><div class="row">${session.timed?'<button id="submit-exam">Submit exam</button>':''}<button id="question-action" class="primary">${checked||session.timed?(session.pos===session.ids.length-1?'Finish session':'Next question →'):'Check answer'}</button></div></div></article></div>`;
  const area=document.querySelector('#answer-area');
  if(question.type==='recall') {
    area.innerHTML=`<label for="recall-answer">Explain it in your own words</label><textarea id="recall-answer" ${checked?'disabled':''} placeholder="Retrieve before revealing…">${escapeHtml(response.text)}</textarea><p class="muted small">Your writing is not automatically graded. Compare it to the model, then assess it honestly.</p>`;
    document.querySelector('#recall-answer').oninput=event=>{response.text=event.target.value;save();};
  } else if(question.type==='sequence') {
    const drawOrder=()=>{area.innerHTML=`<p class="muted">Arrange the steps from first to last. Use the arrow buttons.</p>${response.selected.map((option,index)=>`<div class="sequence-item"><b>${index+1}</b><span>${escapeHtml(question.options[option])}</span><button data-move="${index}" data-delta="-1" aria-label="Move step ${index+1} up" ${checked||index===0?'disabled':''}>↑</button><button data-move="${index}" data-delta="1" aria-label="Move step ${index+1} down" ${checked||index===response.selected.length-1?'disabled':''}>↓</button></div>`).join('')}`;area.querySelectorAll('[data-move]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.move);const next=index+Number(button.dataset.delta);[response.selected[index],response.selected[next]]=[response.selected[next],response.selected[index]];save();drawOrder();area.querySelector(`[data-move="${next}"][data-delta="${button.dataset.delta}"]`)?.focus();});};drawOrder();
  } else {
    area.innerHTML=session.orders[question.id].map((option,index)=>`<button class="choice ${response.selected.includes(option)?'selected':''} ${checked&&question.answer.includes(option)?'correct':''} ${checked&&response.selected.includes(option)&&!question.answer.includes(option)?'incorrect':''}" data-option="${option}" aria-pressed="${response.selected.includes(option)}" ${checked?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+index)}</span><span>${escapeHtml(question.options[option])}</span></button>`).join('');
    area.querySelectorAll('[data-option]').forEach(button=>button.onclick=()=>{const option=Number(button.dataset.option);response.selected=question.type==='multiple'?(response.selected.includes(option)?response.selected.filter(value=>value!==option):[...response.selected,option]):[option];save();area.querySelectorAll('[data-option]').forEach(choice=>{const selected=response.selected.includes(Number(choice.dataset.option));choice.classList.toggle('selected',selected);choice.setAttribute('aria-pressed',String(selected));});});
  }
  if(checked)document.querySelector('#feedback-area').innerHTML=feedback(question,response);
  document.querySelector('#bookmark-question').onclick=event=>{state.bookmarks=state.bookmarks.includes(question.id)?state.bookmarks.filter(id=>id!==question.id):[...state.bookmarks,question.id];save();event.currentTarget.textContent=state.bookmarks.includes(question.id)?'★ Saved':'☆ Save';event.currentTarget.setAttribute('aria-pressed',String(state.bookmarks.includes(question.id)));};
  document.querySelectorAll('[name=confidence]').forEach(input=>input.onchange=()=>{response.confidence=input.value;save();});
  document.querySelector('#hint-button')?.addEventListener('click',()=>{document.querySelector('#hint-area').innerHTML=`<div class="notice">${escapeHtml(question.hint)}</div>`;});
  document.querySelector('#leave-quiz').onclick=()=>{save();location.hash='#home';};
  document.querySelector('#previous-question')?.addEventListener('click',()=>{session.pos--;save();quiz();});
  document.querySelector('#submit-exam')?.addEventListener('click',async()=>{if(await confirmAction('Submit this exam? Unanswered questions count as incorrect.'))finishQuiz();});
  document.querySelector('#question-action').onclick=async()=>{
    if(checked||session.timed){if(session.pos===session.ids.length-1){if(!session.timed||await confirmAction('Submit this exam and reveal results?'))finishQuiz();}else{session.pos++;save();quiz();main.focus();}return;}
    if(question.type==='recall'){
      if(!response.text.trim()){toast('Try writing your answer before revealing the model.');return;}
      document.querySelector('#feedback-area').innerHTML=`<div class="feedback"><h3>Compare your explanation</h3><p>${escapeHtml(question.model)}</p>${refs(question.sources)}<p>Did you capture the essential idea?</p><div class="row"><button data-self="false">Need more practice</button><button data-self="true">Got the key ideas</button></div></div>`;
      document.querySelectorAll('[data-self]').forEach(button=>button.onclick=()=>{response.self=button.dataset.self==='true';recordAnswer(state,question,response.self,response.confidence);session.checked.push(question.id);save();quiz();});return;
    }
    if(!response.selected.length){toast('Select an answer first.');return;}
    recordAnswer(state,question,grade(question,response.selected),response.confidence);session.checked.push(question.id);save();quiz();document.querySelector('#feedback-area').scrollIntoView({block:'nearest'});
  };
  if(session.timed){const tick=()=>{if(!session)return;const seconds=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));const timer=document.querySelector('#timer');if(timer)timer.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;if(seconds===0)finishQuiz(true);};tick();clockInterval=setInterval(tick,1000);}
  save();
}

function finishQuiz(expired=false) {
  if(!session||session.finished)return;clearInterval(clockInterval);session.finished=true;
  const completed=session;let scored=0,correct=0,selfCorrect=0,selfTotal=0;
  const rows=completed.ids.map(id=>{const question=questions.find(item=>item.id===id);const response=completed.responses[id]||{selected:[],confidence:'low',text:'',self:false};const passed=question.type==='recall'?response.self===true:grade(question,response.selected);if(question.type==='recall'){selfTotal++;selfCorrect+=Number(passed);}else{scored++;correct+=Number(passed);}if(completed.timed&&!completed.checked.includes(id))recordAnswer(state,question,passed,response.confidence);return {question,response,passed};});
  session=null;save();
  const weakTopics=[...new Set(rows.filter(row=>!row.passed).map(row=>row.question.topicId))];
  main.innerHTML=`<div class="question-shell">${intro(expired?'Time is up. Here’s your next step.':'One session. Stronger connections.','Use the gaps to choose what comes next.')}<div class="panel"><span class="eyebrow">SESSION RESULTS</span><h1>${correct} / ${scored} <span class="muted">objectively scored</span></h1><p>${scored?Math.round(correct/scored*100)+'% accuracy':'This session used written self-assessment only.'}${selfTotal?` · Written recall: ${selfCorrect}/${selfTotal} self-rated understood.`:''}</p><div class="row"><a class="button" href="#practice/missed">Review missed →</a><a class="button secondary" href="#practice">New session</a><a class="text-link" href="#progress">See all progress →</a></div>${weakTopics.length?`<h3 style="margin-top:25px">Revisit these ideas</h3>${weakTopics.map(id=>`<p><a class="text-link" href="#topic/${id}">${escapeHtml(course.topics.find(topic=>topic.id===id).title)} →</a></p>`).join('')}`:'<p>Good work. Try another topic or return for spaced recall.</p>'}</div>${rows.map(({question,response,passed},index)=>`<details class="panel"><summary>${index+1}. ${passed?'✓':'○'} ${escapeHtml(question.prompt)}</summary><p><b>Your response:</b> ${escapeHtml(question.type==='recall'?response.text||'Not answered':response.selected.length?response.selected.map(option=>question.options[option]).join(' → '):'Not answered')}</p>${feedback(question,response)}</details>`).join('')}</div>`;
}

function flashcards(topicId='all') {
  const pool=cards.filter(card=>topicId==='all'||card.topicId===topicId);
  flashQueue=shuffle(pool.filter(card=>!state.cards[card.id]||state.cards[card.id].due<=Date.now()));flashPosition=0;flashRevealed=false;
  function renderCard(){
    if(flashPosition>=flashQueue.length){const next=pool.map(card=>state.cards[card.id]?.due).filter(Boolean).sort((left,right)=>left-right)[0];main.innerHTML=intro('Give your memory some space.','Spaced review is separate from quiz mastery.')+empty('Review queue complete.',next?`Next scheduled card: ${new Date(next).toLocaleString()}. Again cards return after one minute.`:'No cards in this topic.','#cards','Check due cards')+`<div class="row"><button id="study-all-cards">Study all ${pool.length} cards anyway</button><a class="button secondary" href="#learn">Back to learning</a></div>`;document.querySelector('#study-all-cards').onclick=()=>{flashQueue=shuffle(pool);flashPosition=0;renderCard();};return;}
    const card=flashQueue[flashPosition];const topic=course.topics.find(item=>item.id===card.topicId);
    main.innerHTML=`<div class="question-shell">${intro('A little recall goes a long way.',`${flashPosition+1} / ${flashQueue.length} cards · ${escapeHtml(topic.title)}`)}<a class="text-link" href="#learn">← Choose another topic</a><div class="flashcard"><div class="eyebrow">${flashRevealed?'THE CONNECTION':'RETRIEVE BEFORE YOU REVEAL'}</div>${flashRevealed?`<p>${escapeHtml(card.back)}</p>`:`<h2>${escapeHtml(card.front)}</h2>`}</div>${flashRevealed?`<p class="muted">How easily did you recall it?</p><div class="rating-grid">${['Again','Hard','Good','Easy'].map(rating=>{const next=scheduleCard(state.cards[card.id],rating);return `<button data-rating="${rating}">${rating}<small>${next.interval?next.interval+' days':'1 minute'}</small></button>`;}).join('')}</div>${refs(topic.sources)}`:'<button class="primary" id="reveal-card">Reveal answer ↻</button>'}<p class="muted small">Ratings schedule review. They do not raise your quiz mastery score.</p></div>`;
    document.querySelector('#reveal-card')?.addEventListener('click',()=>{flashRevealed=true;renderCard();});
    document.querySelectorAll('[data-rating]').forEach(button=>button.onclick=()=>{state.cards[card.id]=scheduleCard(state.cards[card.id],button.dataset.rating);save();flashPosition++;flashRevealed=false;renderCard();});
  }
  renderCard();
}

function progressPage() {
  const totals=metrics(questions,state);const rated=Object.keys(state.cards).length;
  const low=questions.filter(question=>state.answers[question.id]?.confidence==='low').length;
  main.innerHTML=intro('Progress you can actually use.','A map of your practice, not a prediction of your exam grade.')+`<div class="stats">${stat('◎',totals.accuracy===null?'—':totals.accuracy+'%','All objective attempts')}${stat('✓',totals.mastered+'/'+totals.total,'Questions mastered')}${stat('▱',rated+'/'+cards.length,'Flashcards reviewed')}${stat('▤',state.completed.length+'/'+course.topics.length,'Lessons marked complete')}</div><div class="row" style="margin-bottom:25px"><a class="button" href="#practice/missed">Review missed</a><a class="button secondary" href="#practice/low">Low confidence (${low})</a><a class="button secondary" href="#practice/bookmarks">Bookmarks (${state.bookmarks.length})</a></div><div class="panel"><h2>Your topic map</h2><div class="table-wrap"><table><thead><tr><th>Topic</th><th>Questions tried</th><th>Accuracy</th><th>Mastery</th><th>Read</th></tr></thead><tbody>${course.topics.map(topic=>{const result=metrics(topicQuestions(topic),state);return `<tr><td><a class="text-link" href="#topic/${topic.id}">${escapeHtml(topic.title)}</a></td><td>${result.seen}/${result.total}</td><td>${result.accuracy===null?'—':result.accuracy+'%'}</td><td>${result.mastery}%</td><td>${state.completed.includes(topic.id)?'✓':'—'}</td></tr>`;}).join('')}</tbody></table></div><details><summary>What does “mastery” mean here?</summary><p>An objective question is counted as mastered after at least two attempts, at least 80% cumulative accuracy, and a correct latest answer marked high confidence. Chapter mastery is the share of all objective questions meeting that rule. Repeated memorization can inflate this measure; use new application questions and explain ideas aloud too.</p><p>Written recall is self-assessed and excluded from objective accuracy and mastery. Flashcard ratings and reading completion remain separate.</p></details></div><a class="text-link" href="#settings">Export, import, or reset progress →</a>`;
}

