function settingsPage() {
  main.innerHTML=intro('Make this space yours.','Comfortable study settings and control over your saved progress.')+`<div class="panel"><div class="settings-row"><div><h3>Color theme</h3><p>Switch between a light desk and a dark study room.</p></div><button id="setting-theme">${state.settings.theme==='light'?'Use dark theme':'Use light theme'}</button></div><div class="settings-row"><div><h3>Science cursor</h3><p>A precise colorful pointer on mouse devices. Text inputs keep the text cursor.</p></div><button id="setting-cursor" aria-pressed="${state.settings.cursor}">${state.settings.cursor?'On':'Off'}</button></div><div class="settings-row"><div><h3>Gentle motion</h3><p>Your system’s reduced-motion preference always takes priority. Manual diagram steps remain available.</p></div><button id="setting-motion" aria-pressed="${state.settings.motion}">${state.settings.motion?'On':'Off'}</button></div></div><div class="panel"><h2>Your progress, your copy.</h2><p>Progress stays in this browser. Export before switching devices or clearing browser data. Existing Exam 1 and 2 missed-question lists remain separate and are included in exports when available.</p><div class="row"><button class="primary" id="export-progress">Export progress</button><label class="button secondary" for="import-progress">Import progress</label><input id="import-progress" type="file" accept="application/json,.json" style="max-width:240px"></div><div class="settings-row"><div><h3>Start Exam 3 fresh</h3><p>Clear Studio progress and schedules. Existing Exam 1 and 2 progress is not cleared.</p></div><button class="danger" id="reset-progress">Reset Exam 3</button></div></div>`;
  document.querySelector('#setting-theme').onclick=()=>{state.settings.theme=state.settings.theme==='light'?'dark':'light';applySettings();save();settingsPage();};
  ['cursor','motion'].forEach(key=>document.querySelector('#setting-'+key).onclick=()=>{state.settings[key]=!state.settings[key];applySettings();save();settingsPage();});
  document.querySelector('#export-progress').onclick=()=>{const legacy={};try{for(const key of ['bio233missed','bio233exam2missed-v2']){const value=localStorage.getItem(key);if(value)legacy[key]=JSON.parse(value);}}catch{}const blob=new Blob([JSON.stringify({app:'bio233-studio',exportedAt:new Date().toISOString(),progress:{...state,session},legacy},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='bio233-study-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  document.querySelector('#import-progress').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('This file is too large for a progress export.');const parsed=JSON.parse(await file.text());if(parsed.app!=='bio233-studio')throw new Error('Choose a BIO 233 Studio export.');const imported=validateProgress(parsed.progress,course.topics,questions,cards);const legacy=parsed.legacy||{};for(const key of ['bio233missed','bio233exam2missed-v2']){if(legacy[key]&&!Array.isArray(legacy[key]))throw new Error('Invalid legacy progress.');if(legacy[key]&&!legacy[key].every(value=>Number.isInteger(value)&&value>=0))throw new Error('Invalid legacy progress values.');}if(!await confirmAction('Replace this browser’s progress with this export? Export your current progress first if you want to keep it.'))return;state=imported;session=imported.session;for(const key of ['bio233missed','bio233exam2missed-v2'])if(legacy[key])localStorage.setItem(key,JSON.stringify(legacy[key]));save();applySettings();toast('Progress imported.');settingsPage();}catch(error){toast(error.message);}};
  document.querySelector('#reset-progress').onclick=async()=>{if(!await confirmAction('Clear all Exam 3 Studio answers, bookmarks, flashcard schedules, and lesson progress? This cannot be undone without an export.'))return;const settings=state.settings;state=freshProgress();state.settings=settings;session=null;save();toast('Exam 3 progress reset. Earlier exam progress is unchanged.');settingsPage();};
}

function labPage() {
  main.innerHTML=intro('See it. Trace it. Understand it.','Original interactive schematics. Simplified to show the key relationships.')+`<div class="diagram-controls">${[['neuron','Neuron explorer'],['potential','Action potential'],['reflex','Reflex pathway']].map(([id,title])=>`<button data-lab="${id}" aria-pressed="${labMode===id}">${title}</button>`).join('')}</div><div class="panel" id="lab-stage"></div><p class="muted small">Diagrams are schematic, not to scale. Values are teaching approximations, not measurements of every neuron.</p>`;
  document.querySelectorAll('[data-lab]').forEach(button=>button.onclick=()=>{clearInterval(animationInterval);labMode=button.dataset.lab;labActive=0;labIdentify=false;labAnswerShown=false;labPage();});
  renderLab();
}
function labRefs(chapter) {
  if(chapter===13)return refs([{id:'ch13-l3',pages:[1,2,3]},{id:'textbook',pages:[65,66,67,68,69,70,71,72]}]);
  if(labMode==='potential')return refs([{id:'ch12-l2',pages:[4,6,7,8]},{id:'textbook',pages:[21,22,23,24]}]);
  return refs([{id:'ch12-l1',pages:[2,3,4,5,6]},{id:'textbook',pages:[4,5,10,11]}]);
}
function renderLab() {
  const stage=document.querySelector('#lab-stage');if(!stage)return;
  if(labMode==='neuron') {
    stage.innerHTML=`<div class="row spread"><div><span class="eyebrow">CHAPTER 12 · STRUCTURE → FUNCTION</span><h2>Meet the neuron.</h2></div><button id="identify-toggle">${labIdentify?'Explore structures':'Test my labels'}</button></div><div class="diagram">${neuronSvg(false,labActive)}</div>${labIdentify?`<h3>What is structure ${labActive+1}?</h3><div class="diagram-controls">${shuffle(neuronParts.map((part,index)=>({part,index}))).map(({part,index})=>`<button data-label-answer="${index}" ${labAnswerShown?'disabled':''}>${part[0]}</button>`).join('')}</div><div id="label-result" role="status">${labAnswerShown?`<div class="feedback"><b>${neuronParts[labActive][0]}</b><p>${neuronParts[labActive][1]}</p></div>`:''}</div><button id="next-label">Next structure →</button><p class="muted small">This is exploratory practice. Use “Identify a structure” in the question bank to record scored results.</p>`:`<div class="diagram-controls">${neuronParts.map((part,index)=>`<button data-part="${index}" aria-pressed="${labActive===index}">${index+1}. ${part[0]}</button>`).join('')}</div><div class="phase-readout" aria-live="polite"><h3>${neuronParts[labActive][0]}</h3><p>${neuronParts[labActive][1]}</p></div>`}${labRefs(12)}`;
    document.querySelector('#identify-toggle').onclick=()=>{labIdentify=!labIdentify;labAnswerShown=false;renderLab();};
    stage.querySelectorAll('[data-part]').forEach(button=>button.onclick=()=>{labActive=Number(button.dataset.part);renderLab();});
    stage.querySelectorAll('[data-label-answer]').forEach(button=>button.onclick=()=>{const correct=Number(button.dataset.labelAnswer)===labActive;stage.querySelectorAll('[data-label-answer]').forEach(choice=>choice.disabled=true);document.querySelector('#label-result').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><b>${correct?'Correct!':'Review this connection:'} ${neuronParts[labActive][0]}</b><p>${neuronParts[labActive][1]}</p></div>`;labAnswerShown=true;});
    document.querySelector('#next-label')?.addEventListener('click',()=>{labActive=(labActive+1)%6;labAnswerShown=false;renderLab();});
  } else if(labMode==='potential') {
    const phase=phases[labActive];stage.innerHTML=`<span class="eyebrow">CHAPTER 12 · FOLLOW THE IONS</span><h2>One action potential, step by step.</h2><div class="lab-columns"><div class="diagram">${potentialSvg(labActive)}</div><div class="phase-readout" aria-live="polite"><div class="eyebrow">STEP ${labActive+1} / ${phases.length}</div><h3>${phase.name}</h3><strong>${phase.voltage}</strong><p>${phase.text}</p></div></div><label for="phase-slider">Choose a phase</label><input id="phase-slider" type="range" min="0" max="5" value="${labActive}" aria-valuetext="${phase.name}"><div class="diagram-controls"><button id="phase-back" ${labActive===0?'disabled':''}>← Previous</button><button id="phase-play" class="primary">${animationInterval?'Pause':'Play sequence'}</button><button id="phase-next" ${labActive===5?'disabled':''}>Next →</button><button id="phase-replay">Replay from start</button></div>${labRefs(12)}`;
    const stop=()=>{clearInterval(animationInterval);animationInterval=null;};
    document.querySelector('#phase-slider').oninput=event=>{stop();labActive=Number(event.target.value);renderLab();document.querySelector('#phase-slider').focus();};
    document.querySelector('#phase-back').onclick=()=>{stop();labActive--;renderLab();};document.querySelector('#phase-next').onclick=()=>{stop();labActive++;renderLab();};
    const play=()=>{if(!state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches){toast('Reduced motion is active. Use Next or the phase slider.');return;}if(labActive===5)labActive=0;animationInterval=setInterval(()=>{labActive++;if(labActive===5)stop();renderLab();},2800);renderLab();};
    document.querySelector('#phase-play').onclick=()=>{if(animationInterval){stop();renderLab();}else play();};document.querySelector('#phase-replay').onclick=()=>{stop();labActive=0;renderLab();play();};
  } else {
    const step=reflexSteps[labActive];stage.innerHTML=`<span class="eyebrow">CHAPTER 13 · INPUT → INTEGRATION → OUTPUT</span><h2>Trace a reflex arc.</h2><div class="diagram"><svg viewBox="0 0 700 170" role="img" aria-label="Five components of a reflex arc: receptor, sensory neuron, integration center, motor neuron, effector.">${reflexSteps.map((part,index)=>`<path d="M${index*137+58} 74H${index*137+153}" stroke="#b7aecb" stroke-width="3"/><circle cx="${index*137+63}" cy="74" r="32" fill="${labActive===index?'#8764c5':'#d9cee9'}"/><text x="${index*137+63}" y="81" text-anchor="middle" fill="${labActive===index?'white':'#51406e'}" font-size="21" font-family="sans-serif">${index+1}</text><text x="${index*137+63}" y="137" text-anchor="middle" fill="var(--text)" font-size="12" font-family="sans-serif">${part[0]}</text>`).join('')}</svg></div><div class="diagram-controls">${reflexSteps.map((part,index)=>`<button data-reflex="${index}" aria-pressed="${index===labActive}">${index+1}. ${part[0]}</button>`).join('')}</div><div class="phase-readout" aria-live="polite"><h3>${step[0]}</h3><p>${step[1]}</p></div><p class="diagram-caption">A generic pathway, not an anatomical cross-section. Spinal reflex integration does not require conscious decision-making, although information can also ascend to the brain.</p>${labRefs(13)}`;stage.querySelectorAll('[data-reflex]').forEach(button=>button.onclick=()=>{labActive=Number(button.dataset.reflex);renderLab();});
  }
}

function route() {
  main.querySelectorAll('audio').forEach(player=>player.pause());
  clearInterval(clockInterval);clearInterval(animationInterval);animationInterval=null;
  if(audioUrl){URL.revokeObjectURL(audioUrl);audioUrl=null;}
  const parts=location.hash.slice(1).split('/');const page=parts[0]||'home';
  document.querySelectorAll('[data-route]').forEach(link=>{const active=link.dataset.route===(page==='topic'?'learn':page==='quiz'?'practice':page);link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
  document.querySelector('#view-name').textContent=({home:'Overview',learn:'Learn & explore',topic:'Learn & explore',practice:'Practice',quiz:'Study session',cards:'Flashcards',progress:'My progress',sources:'Lecture library',settings:'Settings',lab:'Visual lab'})[page]||'Overview';
  if(page==='learn')learn(parts[1]);else if(page==='topic')lesson(parts[1]);else if(page==='practice')practiceSetup(parts.slice(1));else if(page==='quiz')quiz();else if(page==='cards')flashcards(parts[1]);else if(page==='progress')progressPage();else if(page==='sources')sourceLibrary();else if(page==='settings')settingsPage();else if(page==='lab')labPage();else home();
  window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});
}

async function init() {
  const response=await fetch('./exam3-content.json?v=20261110');if(!response.ok)throw new Error('The course content could not be loaded. Please reload.');course=await response.json();
  questions=course.topics.flatMap(topic=>topic.questions.map(question=>({...question,topicId:topic.id,chapter:topic.chapter})));
  cards=course.topics.flatMap(topic=>topic.cards.map((card,index)=>({...card,id:topic.id+'-card-'+index,topicId:topic.id})));
  const neuronTopic=course.topics.find(topic=>/neuron.*structure|structure.*neuron|neuron.*classification/i.test(topic.title))||course.topics.find(topic=>topic.chapter===12);
  neuronParts.forEach((part,index)=>questions.push({id:'visual-neuron-'+index,type:'label',part:index,topicId:neuronTopic.id,chapter:12,prompt:`Identify highlighted structure ${index+1} in the neuron diagram.`,options:neuronParts.map(item=>item[0]),answer:[index],explanations:[part[1]],hint:'Consider the position of the structure and its role in receiving, conducting, or transmitting a signal.',sources:neuronTopic.sources}));
  state=freshProgress();try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=validateProgress(JSON.parse(raw),course.topics,questions,cards);}catch{toast('Saved progress could not be read. A fresh session is available; your other exams are unchanged.');}
  session=state.session;applySettings();save();
  document.querySelector('#theme-toggle').onclick=()=>{state.settings.theme=state.settings.theme==='light'?'dark':'light';applySettings();save();};
  window.addEventListener('hashchange',route);
  document.querySelector('.skip').onclick=event=>{event.preventDefault();main.focus();main.scrollIntoView({block:'start'});};
  window.addEventListener('beforeunload',save);
  window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY)toast('Progress changed in another tab. Reload before continuing to avoid overwriting it.');});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&session?.timed&&Date.now()>=session.deadline&&location.hash==='#quiz')finishQuiz(true);});
  route();
}
init().catch(error=>{main.innerHTML=empty('We couldn’t open the study content.',escapeHtml(error.message),'index.html','Reload the hub');});
